INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_soc_ssh-brute-to-persistence_t1', 'lab_soc_ssh-brute-to-persistence', 1, 'One external address is responsible for the suspicious activity. Which is it, and when does it first appear?', '103.84.22.17, first at 02:11:04 trying invalid usernames (oracle, postgres, test). That early block matters: username guessing before password guessing is the shape of an automated scan, not a user mistyping.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_soc_ssh-brute-to-persistence_t2', 'lab_soc_ssh-brute-to-persistence', 2, 'The attacker eventually gets in. Which account, and why is that more interesting than the root attempts?', 'deploy, at 02:14:14, by password. More interesting than root for two reasons: root was rate-limited out at 02:13:00 so those attempts went nowhere, and deploy normally authenticates by public key from 10.14.3.22. A password login for a key-only account, from an external address, is the actual finding.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_soc_ssh-brute-to-persistence_t3', 'lab_soc_ssh-brute-to-persistence', 3, 'Name two things done after the login that you would call persistence, and quote the lines.', 'First, a new SSH key for deploy accepted from 185.62.189.44 at 02:15:02, a different address from the one that logged in. Second, useradd creating svc-backup in the sudo group at 02:15:40, which then logs in by key at 02:44:09. Either survives a password reset on deploy, which is why resetting deploy alone would not end this.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_soc_ssh-brute-to-persistence_t4', 'lab_soc_ssh-brute-to-persistence', 4, 'Something in this log is an attempt to blind you. What, and what does it mean for your investigation?', 'systemctl disable --now rsyslog at 02:16:03. Logging was switched off on the host, so anything after that point is missing locally and you cannot treat the end of this file as the end of the activity. Pull the same window from the central log collector, and if nothing was being forwarded, say plainly that the timeline has a hole rather than assuming it ends here.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_soc_ssh-brute-to-persistence_t5', 'lab_soc_ssh-brute-to-persistence', 5, 'Is this a breach, and what do you do in the next ten minutes?', 'Yes: an external address authenticated successfully, escalated to root, ran a downloaded binary and created an account. In ten minutes: isolate the host at the network level while keeping your access, block 185.62.189.44 and 103.84.22.17 at the egress and ingress points, disable deploy and svc-backup rather than deleting them, and preserve the disk and memory before anyone reboots. Then tell the business which host and what it can no longer do.');

INSERT OR REPLACE INTO labs (id, title, role, level, brief, artifact_kind, artifact_name, is_free, created_at) VALUES ('lab_network_dns-txt-exfil', 'Something is talking in TXT records', 'network', 'mid', 'Eleven minutes of resolver logs from a single office subnet, pulled because the weekly report flagged an unusual query mix. Nobody has complained and nothing is down. Find what is wrong with it, and decide what you would do without causing an outage.', 'table', 'dns-queries-0914-0925.csv', 1, '2026-11-20T16:36:32.973Z');
