DELETE FROM lab_tasks WHERE lab_id = 'lab_network_webshell-in-access-log';
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_network_webshell-in-access-log_t1', 'lab_network_webshell-in-access-log', 1, 'A scan runs at 09:11. How do you spot it, and which single request in it matters?', 'Five requests in three seconds from 91.214.76.33 with the user agent python-requests, all to paths nobody links to: /admin, /wp-login.php, /phpmyadmin, /.git/config, /.env. Four return 404. The one that matters is /.env returning 200 with 614 bytes, because that file holds application credentials. One success in a wall of failures is the whole finding.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_network_webshell-in-access-log_t2', 'lab_network_webshell-in-access-log', 2, 'Eleven minutes later the same address logs in successfully. Connect the two events.', 'POST /api/v1/login at 09:22:40 returns 200, which means credentials worked. The credentials came from the .env file read at 09:11:04. The gap is the attacker reading what they took. Immediately after, GET /api/v1/users?limit=500 returns 214 KB and /api/v1/orders?limit=1000 returns 884 KB: that is the customer and order data leaving, and the response sizes are how you size the breach.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_network_webshell-in-access-log_t3', 'lab_network_webshell-in-access-log', 3, 'Identify the web shell and the exact moment it starts working.', 'POST /admin/media/upload at 09:26:55 returns 201 Created. Fifteen seconds later GET /uploads/2026/11/thumb_9f2a.php?c=id returns 200 with 54 bytes. A .php file in an uploads directory, taking a c parameter, returning short responses, is a command shell. The upload endpoint accepted a PHP file and the uploads directory executes PHP, which is two separate defects.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_network_webshell-in-access-log_t4', 'lab_network_webshell-in-access-log', 4, 'A second address appears at 09:28. What does that change about your response?', '45.33.19.8 with curl hits the same shell at 09:28 and again at 09:44 to tar up /var/www. Either the attacker moved address or access was handed on. Either way, blocking 91.214.76.33 alone achieves nothing: the shell is the access, not the address. Delete the file, stop PHP executing in uploads, and rotate every credential that was in that .env.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_network_webshell-in-access-log_t5', 'lab_network_webshell-in-access-log', 5, 'Write the one-paragraph summary you would send the business.', 'Between 09:11 and 09:44 an attacker read a configuration file exposed at /.env, used the credentials in it to sign in to the API, downloaded roughly 500 customer records and 1000 orders, uploaded a web shell through the media upload endpoint and used it to run commands and archive the web root. The server is compromised, the data in those two API responses should be treated as disclosed, and every credential in that file must be rotated now. Give times, what was taken and what you need, and leave the speculation out.');

INSERT OR REPLACE INTO labs (id, title, role, level, brief, artifact_kind, artifact_name, is_free, created_at) VALUES ('lab_pentest_nmap-what-first', 'Nine ports open. Where do you start?', 'pentest', 'fresher', 'A service scan of a staging host that is in scope for a week-long engagement. You have limited time and the client will judge the report by what you found that matters. Decide your order and be able to defend it.', 'log', 'nmap-staging.txt', 1, '2026-11-20T16:36:32.973Z');
